            if i0 == i1:
                mode = 'i'; break
            elif (i1 - i0 > 0) == (j1 - j0 > 0):
                mode = 'd'; break
            else:
                mode = 's'; break
    def key(i, j):
        if mode == 'i': return i
        if mode == 's': return i + j
        return i - j
    info = {}
    for i, j, c in cells:
        k = key(i, j)
        if c not in info:
            info[c] = k
    colors = list(info)
    n = len(colors)
    # assign each color to residue key mod n; resolve collisions by sum order
    cycle = [None] * n
    for c in sorted(colors, key=lambda c: info[c]):
        r = info[c] % n
        while cycle[r] is not None:
            r = (r + 1) % n
        cycle[r] = c
    return [[cycle[key(i, j) % n] for j in range(W)] for i in range(H)]
